-- The Advantage extended field types of Clipper (NTX) and FoxPro (CDX) DBF
-- tables, with memo, binary and image data from empty to several blocks and
-- memos that grow and shrink by updates. ShortDate and Image need
-- AdsCreateTable (SQL cannot create them).
-- types: ntx cdx
CREATE TABLE dbf_ext (e_dbl DOUBLE, e_int INTEGER, e_long LONGINT, e_guid GUID, e_vchar VARCHAR(8), e_nchar NCHAR(3), e_nvchar NVARCHAR(4), e_nmemo NMEMO, e_blob BLOB, e_memo MEMO);
